'use client';

// The main screen.
import {Dialog, Selector, Banner, Stack} from "@astryxdesign/core";
import {Skeleton} from "@astryxdesign/core/Skeleton";
import {getIcon} from "@astryxdesign/core/globalIconRegistry";

export default function App({open, items}: {open: boolean; items: string[]}) {
  const Icon = getIcon('close');
  const css = `color: var(--color-border); box-shadow: var(--shadow-low);`;
  return (
    <Stack gap="space2" rowGap={'space1.5'}>
      {/* keep this comment */}
      <Dialog isShown={open} onOpenChange={() => {}} title="Hello">
        <Selector options={items} />
      </Dialog>
      <Banner endContent={<Icon />} container="card" collapsible={{
        defaultIsOpen: true
      }} />
      <Skeleton radius={1} style={{boxShadow: "var(--shadow-low)"}} />
    </Stack>
  );
}

import {TopNav, TopNavHeading} from "@astryxdesign/core";
import {StatusDot} from "@astryxdesign/core";

export function Header() {
  return (
    <TopNav heading="Shop" endContent={<span>cart</span>}>
      <TopNavHeading heading="Home" />
      <StatusDot variant='success' />
    </TopNav>
  );
}

import {Text, Switch, Avatar, TabList, Dialog, Table} from '@astryxdesign/core';

export function Panel({data}: {data: unknown[]}) {
  return (
    <>
      <Text color='accent'>Hi</Text>
      <Switch labelSpacing='hug' label="On" />
      <Avatar size='md' name="A" />
      <TabList />
      <Dialog position={{start: 0, top: 8}} />
      <Table data={data} aria-label='Rows' role='grid' />
    </>
  );
}
